define('ui/liststyler',['jquery', 'lodash', 'core/pluginifier', 'util/capitalize'], function ($, _, Pluginifier, capitalize) {
  'use strict';

  $ = $ && Object.prototype.hasOwnProperty.call($, 'default') ? $['default'] : $;
  _ = _ && Object.prototype.hasOwnProperty.call(_, 'default') ? _['default'] : _;
  Pluginifier = Pluginifier && Object.prototype.hasOwnProperty.call(Pluginifier, 'default') ? Pluginifier['default'] : Pluginifier;
  capitalize = capitalize && Object.prototype.hasOwnProperty.call(capitalize, 'default') ? capitalize['default'] : capitalize;
  var ns = 'liststyler';
  var currStyle = '';
  var defaults = {
    selected: null
  };
  var listStyles = {
    none: '',
    disc: '\u25cf',
    circle: '\u25cb',
    square: '\u25fd',
    decimal: '1',
    'decimal-leading-zero': '01',
    'lower-alpha': 'a',
    'upper-alpha': 'A',
    'lower-roman': 'i',
    'upper-roman': 'I',
    'lower-greek': '\u03b1',
    armenian: '\u0531',
    georgian: '\u10d0',
    'decimal-period': '1.',
    'decimal-parenthesis': '1)',
    'lower-alpha-period': 'a.',
    'lower-alpha-parenthesis': 'a)',
    'upper-alpha-period': 'A.',
    'upper-alpha-parenthesis': 'A)'
  };
  function populate(selectBox, selectedStyle) {
    _.forOwn(listStyles, function (symbol, style) {
      selectBox.options.add(new Option(capitalize(style.replace(/-/g, ' ')), style, false, style === selectedStyle));
    });
  }
  function formatState(state) {
    var symbol = listStyles[state.id];
    return $('<span/>', {
      text: state.text,
      'data-symbol': symbol
    });
  }
  var ListStyler = {
    init: function init(options) {
      return this.each(function () {
        var $elt = $(this);
        options = $.extend(true, {}, defaults, options);
        populate(this, options.selected);
        currStyle = options.selected;
        $elt.on('change', function () {
          $elt.trigger('stylechange.' + ns, {
            newStyle: this.value,
            oldStyle: currStyle
          });
          currStyle = this.value;
        });
        $elt.select2({
          formatResult: formatState,
          width: 'element',
          minimumResultsForSearch: Infinity
        });
        $elt.trigger('create.' + ns);
      });
    },
    destroy: function destroy() {
      this.each(function () {
        var $elt = $(this);
        $elt.trigger('destroy.' + ns);
      });
    }
  };
  Pluginifier.register(ns, ListStyler);
});
