define('util/bytes',[],function () {
  'use strict';
  var bytesUtil = {
    hrSize: function hrSize(bytes) {
      var units = ['B', 'kB', 'MB', 'GB', 'TB'];
      var unit = 0;
      var thresh = 1024;
      bytes = bytes || 0;
      while (bytes >= thresh) {
        bytes /= thresh;
        unit++;
      }
      return bytes.toFixed(2) + units[unit];
    }
  };
  return bytesUtil;
});
