define('core/communicator/poll',['lodash', 'core/polling', 'core/promise', 'core/request'], function (_, pollingFactory, Promise, coreRequest) {
  'use strict';

  _ = _ && Object.prototype.hasOwnProperty.call(_, 'default') ? _['default'] : _;
  pollingFactory = pollingFactory && Object.prototype.hasOwnProperty.call(pollingFactory, 'default') ? pollingFactory['default'] : pollingFactory;
  Promise = Promise && Object.prototype.hasOwnProperty.call(Promise, 'default') ? Promise['default'] : Promise;
  coreRequest = coreRequest && Object.prototype.hasOwnProperty.call(coreRequest, 'default') ? coreRequest['default'] : coreRequest;
  var defaults = {
    timeout: 30 * 1000,
    interval: 30 * 1000,
    throttle: 1000
  };
  var pollProvider = {
    name: 'poll',
    init() {
      var config = _.defaults(this.getConfig(), defaults);
      if (!config.service) {
        return Promise.reject(new Error('You must provide a service URL'));
      }
      this.messagesQueue = [];
      this.request = function request() {
        return new Promise(resolve => {
          var promises = [];
          var req = _.map(this.messagesQueue, function (msg) {
            promises.push(msg.promise);
            return {
              channel: msg.channel,
              message: msg.message
            };
          });
          var defaultRequestParams = {
            url: config.service,
            method: 'POST',
            headers: {},
            data: JSON.stringify(req),
            dataType: 'json',
            contentType: 'application/json',
            sequential: true,
            noToken: false,
            timeout: config.timeout
          };
          var extendedRequestParams = Object.assign({}, defaultRequestParams, config.requestParams);
          this.messagesQueue = [];
          coreRequest(extendedRequestParams).then(response => {
            _.forEach(promises, function (promise, idx) {
              promise.resolve(response.responses && response.responses[idx]);
            });
            if (!this.polling.is('stopped')) {
              _.forEach(response.messages, msg => {
                if (msg.channel) {
                  this.trigger('message', msg.channel, msg.message);
                } else {
                  this.trigger('message', 'malformed', msg);
                }
              });
            }
            this.trigger('receive', response);
            resolve();
          }).catch(error => {
            error.source = 'network';
            error.purpose = 'communicator';
            _.forEach(promises, function (promise) {
              promise.reject(error);
            });
            this.trigger('error', error);
            resolve();
          });
        });
      };
      var callRequest = () => this.request();
      this.polling = pollingFactory({
        interval: config.interval,
        autoStart: false,
        action() {
          var async = this.async();
          callRequest().then(function () {
            async.resolve();
          });
        }
      });
      this.throttledSend = _.throttle(() => {
        this.polling.next();
      }, config.throttle);
      return Promise.resolve();
    },
    destroy() {
      var stopped;
      if (this.polling) {
        stopped = new Promise(resolve => {
          this.polling.off('stop.api').on('stop.api', resolve).stop();
        });
      } else {
        stopped = Promise.resolve();
      }
      return stopped.then(() => {
        this.polling = null;
        this.throttledSend = null;
        this.messagesQueue = null;
      });
    },
    open() {
      if (this.polling) {
        return new Promise(resolve => {
          this.polling.off('next.api').on('next.api', resolve).start().next();
        });
      }
      return Promise.reject(new Error('The communicator has not been properly initialized'));
    },
    close() {
      if (this.polling) {
        return new Promise(resolve => {
          this.polling.off('stop.api').on('stop.api', resolve).stop();
        });
      }
      return Promise.reject(new Error('The communicator has not been properly initialized'));
    },
    send(channel, message) {
      var pending = {
        channel: channel,
        message: message
      };
      var promise = new Promise(function (resolve, reject) {
        pending.promise = {
          resolve: resolve,
          reject: reject
        };
      });
      this.messagesQueue.push(pending);
      this.throttledSend();
      return promise;
    }
  };
  return pollProvider;
});
